    <button data-role="close" style="
      padding: 10px 16px;
      font-size: 16px;
      border: none;
      border-radius: 12px;
      background: #4a90e2;
      color: #ffffff;
      cursor: pointer;
      width: 100%;
    ">\u0417\u0430\u043A\u0440\u044B\u0442\u044C</button>
